const listLiveExportAttempts = `-- name: ListLiveExportAttempts :many
SELECT id, attempt_id
FROM export_job
WHERE attempt_id IS NOT NULL
  AND (status = 'ready' OR (status = 'running' AND lease_until >= now()))
`

type ListLiveExportAttemptsRow struct {
	ID        uuid.UUID
	AttemptID *uuid.UUID
}

// Attempts whose files must survive the orphan sweep (mục 2.5.4).
func (q *Queries) ListLiveExportAttempts(ctx context.Context) ([]ListLiveExportAttemptsRow, error) {
	rows, err := q.db.Query(ctx, listLiveExportAttempts)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListLiveExportAttemptsRow
	for rows.Next() {
		var i ListLiveExportAttemptsRow
		if err := rows.Scan(&i.ID, &i.AttemptID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPendingCleanupAfter = `-- name: ListPendingCleanupAfter :many
SELECT id, file_name, job_id, attempt_id, reason, created_at, done_at, attempts FROM export_file_cleanup
WHERE done_at IS NULL
  AND (created_at, id) > ($1::timestamptz, $2::uuid)
ORDER BY created_at ASC, id ASC
LIMIT $3
`

type ListPendingCleanupAfterParams struct {
	AfterCreatedAt pgtype.Timestamptz
	AfterID        uuid.UUID
	BatchLimit     int32
}

// Keyset page over pending cleanup obligations so one prune sweep visits every
// pending row even when an older page fails entirely (r2 R2-02).
func (q *Queries) ListPendingCleanupAfter(ctx context.Context, arg ListPendingCleanupAfterParams) ([]ExportFileCleanup, error) {
	rows, err := q.db.Query(ctx, listPendingCleanupAfter, arg.AfterCreatedAt, arg.AfterID, arg.BatchLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ExportFileCleanup
	for rows.Next() {
		var i ExportFileCleanup
		if err := rows.Scan(
			&i.ID,
			&i.FileName,
			&i.JobID,
			&i.AttemptID,
			&i.Reason,
			&i.CreatedAt,
			&i.DoneAt,
			&i.Attempts,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listStaleQueuedExports = `-- name: ListStaleQueuedExports :many
SELECT id, created_at
FROM export_job
WHERE status = 'queued'
  AND created_at < $1
  AND (created_at, id) > ($2::timestamptz, $3::uuid)
ORDER BY created_at ASC, id ASC
LIMIT $4
`

type ListStaleQueuedExportsParams struct {
	Before       pgtype.Timestamptz
	AfterCreated pgtype.Timestamptz
	AfterID      uuid.UUID
	BatchLimit   int32
}

type ListStaleQueuedExportsRow struct {
	ID        uuid.UUID
	CreatedAt pgtype.Timestamptz
}

// Queued jobs whose River delivery may be exhausted (r1 R1-16); keyset-paged
// on (created_at, id). The caller checks river_job liveness before failing.
func (q *Queries) ListStaleQueuedExports(ctx context.Context, arg ListStaleQueuedExportsParams) ([]ListStaleQueuedExportsRow, error) {
	rows, err := q.db.Query(ctx, listStaleQueuedExports,
		arg.Before,
		arg.AfterCreated,
		arg.AfterID,
		arg.BatchLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListStaleQueuedExportsRow
	for rows.Next() {
		var i ListStaleQueuedExportsRow
		if err := rows.Scan(&i.ID, &i.CreatedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listStaleRunningExports = `-- name: ListStaleRunningExports :many
SELECT id, attempt_id, file_name, lease_until
FROM export_job
WHERE status = 'running'
  AND lease_until < $1
  AND (lease_until, id) > ($2::timestamptz, $3::uuid)
ORDER BY lease_until ASC, id ASC
LIMIT $4
`

type ListStaleRunningExportsParams struct {
	Before     pgtype.Timestamptz
	AfterLease pgtype.Timestamptz
	AfterID    uuid.UUID
	BatchLimit int32
}

type ListStaleRunningExportsRow struct {
	ID         uuid.UUID
	AttemptID  *uuid.UUID
	FileName   *string
	LeaseUntil pgtype.Timestamptz
}

// Reconciler candidates (mục 2.4); the caller checks river_job liveness.
// Keyset-paged on (lease_until, id) so live rows skipped by the caller do not
// starve later stale rows (review r1 R1-18).
func (q *Queries) ListStaleRunningExports(ctx context.Context, arg ListStaleRunningExportsParams) ([]ListStaleRunningExportsRow, error) {
	rows, err := q.db.Query(ctx, listStaleRunningExports,
		arg.Before,
		arg.AfterLease,
		arg.AfterID,
		arg.BatchLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListStaleRunningExportsRow
	for rows.Next() {
		var i ListStaleRunningExportsRow
		if err := rows.Scan(
			&i.ID,
			&i.AttemptID,
			&i.FileName,
			&i.LeaseUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

